import {energy01Data as data} from './energy01-data.js?v=20261027-energy01';
import {developmentPaths} from './development-data.js?v=20261026-development01';
export {energy01Data} from './energy01-data.js?v=20261027-energy01';
export const energy01Views={
 'dev-energy-consumption':[['totals','Total or per person'],['map','Energy use map'],['food','Food availability'],['water','Water withdrawals']],
 'dev-energy-types':[['classify','Classify sources'],['finite','Finite stock'],['wind','Renewable flow'],['carrier','Source to carrier']],
 'dev-energy-natural-gas':[['supply','Develop the supply'],['dispatch','Meet demand'],['emissions','Follow emissions'],['evaluate','Weigh the tradeoffs']],
 'dev-energy-wind':[['rotor','Wind to electricity'],['low','Low-wind comparison'],['balance','Balance the system'],['siting','Choose the site']],
 'dev-energy-uk-mix':[['mix','2025 primary mix'],['groups','Unpack the categories'],['history','1990 and 2025'],['basis','Choose the denominator']]
};
export const energy01Requirements=Object.fromEntries(Object.entries(energy01Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const energy01Animated=(k,v)=>k==='dev-energy-types'?['finite','wind'].includes(v):k==='dev-energy-natural-gas'?v!=='evaluate':k==='dev-energy-wind'?v!=='siting':false;
export const energyUseBin=v=>v==null?-1:v<1000?0:v<2000?1:v<4000?2:3;
export const energyShare=(value,total)=>100*value/total;
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#c5d5cd',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const token=(x,y,c='#edb396',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f0e8d8"/>`;
const box=(x,y,w,a,b)=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a6c1c8"/>`+T(x+12,y+24,a)+(b?T(x+12,y+47,b,11):'');
const title=s=>T(20,30,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,t)=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`;
const sources={energy:link('https://databank.worldbank.org/metadataglossary/world-development-indicators/series/EG.USE.PCAP.KG.OE','WDI / IEA: primary energy definition')+' · '+link(data.energy.source,'2022 source values')+'. API updated 8 October 2026; CC BY 4.0. kg oil equivalent is a common energy unit, not litres of oil or electricity alone. National estimates hide inequality and methodological differences.',food:link(data.food.source,'FAO food balances 2010–2023, released 28 October 2025')+'. Regional ordering describes dietary energy supply, not a map of actual intake, nutrition or individual access. No invented regional calorie values.',water:link(data.water.source,'UN SDG report 2025: 2022 freshwater withdrawals')+' · '+link('https://www.unwater.org/sites/default/files/2024-12/SDG6_Indicator_Report_642_Progress-of-water-stress_2024_EN.pdf','FAO / UN-Water: regional context')+'. Sector shares refer to withdrawals, not all rainfall or permanent consumption. Farming, industry and urban demand vary across regions.',uk:link(data.uk.source,'DESNZ UK Energy in Brief 2026 dataset')+' · '+link('./geography/data/energy01-uk-selected.json','Retained selected source cells')+'. Published 3 August 2026, 2025 annual data. Inland primary energy; excludes non-energy use. OGL 3.0. Grouped primary electricity includes nuclear, wind, solar, hydro and net imports; not entirely renewable.',gas:link('https://www.eia.gov/energyexplained/natural-gas/use-of-natural-gas.php','EIA: natural gas services')+' · '+link('https://www.eia.gov/energyexplained/natural-gas/natural-gas-and-the-environment.php','EIA: production and environmental effects')+'. Symbolic extraction, output and emissions, not a named plant, measured leak rate or emissions comparison per kWh.',wind:link('https://www.eia.gov/energyexplained/wind/electricity-generation-from-wind.php','EIA: wind generation')+' · '+link('https://www.eia.gov/energyexplained/wind/wind-energy-and-the-environment.php','EIA: wind impacts')+'. Illustrative mechanism, not measured power, operating thresholds, a forecast or a named project.',types:link('https://www.eia.gov/energyexplained/what-is-energy/sources-of-energy.php','EIA: primary resources and secondary carriers')+'. Classification, replacement times and variability are distinct. Invented stock values illustrate finite extraction, not depletion dates.'};
const source=k=>`<p class="geo-caption">${sources[k]}</p>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const colours=['#ead1ae','#b9c6a1','#7eaaa0','#ecad92','#a9b5d1'];
const ukRows=data.uk.rows.slice(0,5),total=data.uk.rows[5][2];
export function energy01Evidence(k='energy'){
 let b='',c='',s=k;
 if(k==='energy'||k==='map'){
 b=title('PRIMARY ENERGY USE PER PERSON · 2022')+T(20,51,'kg oil equivalent / person · four selected countries',11);
 for(const p of developmentPaths){const v=data.energy.countries.find(x=>x.code===p.code)?.value;b+=`<path d="${p.d}" fill="${v==null?'#697e86':colours[energyUseBin(v)]}" stroke="#234355" stroke-width="0.5"/>`;}
 for(const[i,a]of ['<1,000','1,000–<2,000','2,000–<4,000','≥4,000'].entries())b+=`<rect x="${20+i*105}" y="275" width="13" height="13" fill="${colours[i]}"/>`+T(37+i*105,286,a,9);
 b+=T(20,326,'Grey = not selected. North ↑. Actual generalised outlines.',10);c='Four-country primary-energy choropleth, with an explicit key and common year. Grey countries are outside the selection; this is not a complete world ranking.';s='energy';
 return fig(b,c)+source(s)+`<p class="geo-caption">${link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth public-domain country geometry')}.</p>`+table('2022 primary energy use, rounded kg oil equivalent per person',['Country','kg oe / person'],data.energy.countries.map(x=>[x.name,x.value.toFixed(0)]));
 }
 if(k==='water'){b=title('GLOBAL FRESHWATER WITHDRAWALS · 2022')+T(20,53,'Percent of total withdrawals · UN SDG reporting',11);let x=20;for(const[i,[n,v]]of data.water.rows.entries()){b+=`<rect x="${x}" y="95" width="${v*4}" height="65" fill="${colours[i]}"/>`;x+=v*4;b+=`<rect x="20" y="${195+i*38}" width="15" height="15" fill="${colours[i]}"/>`+T(45,208+i*38,n+': '+v+'%',13);}c='Global sector shares of freshwater withdrawals, 2022. A withdrawal can partly return to the water system; these are not household access percentages.';return fig(b,c)+source('water')+table('2022 shares of global freshwater withdrawals',['Sector','Percent'],data.water.rows);}
 if(k==='mix'||k==='history'){
 const history=k==='history';b=title(history?'UK PRIMARY ENERGY · MATCHED SOURCE CATEGORIES':'UK INLAND PRIMARY ENERGY · 2025')+T(20,52,'Million tonnes of oil equivalent (mtoe) · zero baseline',11);
 for(const[i,r]of ukRows.entries()){let y=84+i*47;b+=T(20,y,r[0],11);if(history){b+=`<rect x="173" y="${y-12}" width="${r[1]/80*185}" height="10" fill="#a6c1b0"/><rect x="173" y="${y+1}" width="${r[2]/80*185}" height="10" fill="#edb396"/>`+T(365,y-3,r[1].toFixed(2),10)+T(365,y+10,r[2].toFixed(2),10);}else b+=`<rect x="173" y="${y-12}" width="${r[2]/80*185}" height="18" fill="${colours[i]}"/>`+T(365,y+2,r[2].toFixed(2),11);}
 b+=line('M173 306H358')+T(173,321,'0',9)+T(255,321,'40',9)+T(345,321,'80',9);if(history)b+=T(20,342,'Green: 1990 · Coral: 2025',11);else b+=T(20,342,'Total: '+total.toFixed(2)+' mtoe · grouped source cells',11);
 c=history?'Two matched years with the same source categories, scale and units. Source-cell precision is retained; quantities differ from percentage shares.':'Source-cell quantities in the 2025 UK inland primary-energy account. Read the grouped-category definitions before classifying any share as renewable.';
 return fig(b,c)+source('uk')+table(history?'UK primary consumption, source cells':'UK 2025 primary consumption, source cells',history?['Category','1990 mtoe','2025 mtoe']:['Category','2025 mtoe'],data.uk.rows.map(r=>history?[r[0],r[1].toFixed(2),r[2].toFixed(2)]:[r[0],r[2].toFixed(2)]));
 }
 return '';
}
const turbine=(x,y,t,scale=1)=>`<g transform="translate(${x} ${y}) scale(${scale})"><path d="M-7 130L-3 0H3L7 130Z" fill="#a8c1bf" stroke="#e8e8d9"/><g transform="rotate(${t*360})">${[0,120,240].map(a=>`<path transform="rotate(${a})" d="M0 0Q-18-35-3-93Q8-93 7-65L5-12Z" fill="#dddcc9" stroke="#a6bdb9"/>`).join('')}</g><circle r="9" fill="#e7b596" stroke="#f2e5ce"/></g>`;
const windLines=t=>[0,1,2].map(i=>line(`M${20+t*38} ${95+i*38}h65`,'#9bc6cc',2)+token(20+t*65,95+i*38,'#a6c9ce',3)).join('');
export function energy01Scene(k,v,t=0){if(!energy01Views[k])return '';if(!energy01Requirements[k].includes(v))v=energy01Requirements[k][0];t=energy01Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s=k==='dev-energy-natural-gas'?'gas':k==='dev-energy-wind'?'wind':'types';
 if(k==='dev-energy-consumption'){
 if(['map','water'].includes(v))return energy01Evidence(v);
 if(v==='food'){b=title('FOOD AVAILABILITY · REGIONAL PATTERN, 2023')+box(20,70,400,'Europe / Americas / Oceania','Above the world mean')+box(20,153,400,'Asia','Rising towards the world mean')+box(20,236,400,'Africa','Lower; limited change in the reported period');c='FAO regional ordering, not a numerical calorie chart. Availability differs from actual intake and does not describe every household.';s='food';}
 else{b=title('TOTAL USE = POPULATION × USE PER PERSON')+box(20,70,190,'A: 10 million people','4 units / person')+box(230,70,190,'B: 100 million people','1 unit / person')+T(50,198,'40 million units',19)+T(258,198,'100 million units',19)+`<rect x="20" y="230" width="160" height="25" fill="#a9c4af"/><rect x="20" y="275" width="400" height="25" fill="#edb396"/>`+T(20,330,'Invented teaching units · bars start at zero',11);c='Two invented populations and per-person rates. Multiply before comparing national totals; these bars are not measured country consumption.';s='energy';}
 }
 if(k==='dev-energy-types'){
 if(v==='classify'){b=title('REPLACEMENT ON HUMAN TIMESCALES')+box(20,70,190,'Renewable flows','Wind / solar / HEP')+box(230,70,190,'Finite fossil fuels','Coal / oil / natural gas')+box(20,190,190,'Potentially renewable','Biomass with replenishment')+box(230,190,190,'Finite nuclear fuel','Uranium: not fossil');c='A static classification, not a ranking of carbon impact or reliability. Renewable flows and managed biological stocks have different constraints.';}
 else if(v==='finite'){b=title('FINITE GEOLOGICAL STOCK')+T(20,63,'Invented units · no human-scale renewal',12)+`<rect x="40" y="110" width="300" height="80" fill="#2b4d61" stroke="#c0cfc6"/><rect x="40" y="110" width="${(100-20*t)*3}" height="80" fill="#a9c2ad"/>`+T(55,156,'Stock: '+(100-20*t).toFixed(0),20)+line('M347 150H420')+token(347+73*t,150)+T(20,247,'Start 100 − extraction 20 = 80',17)+T(20,325,'Replay repeats the illustration, not geological renewal.',10);c='A finite-stock extraction illustration, not a real reserve estimate or depletion date. The loop does not regenerate fossil fuel.';}
 else if(v==='wind'){b=title('REPLENISHED FLOW → ELECTRICITY')+windLines(t)+turbine(170,155,t,.9)+line('M170 270H350')+token(170+180*t,270)+box(265,215,155,'Generator / grid','Energy transfer')+T(20,328,'Renewable does not mean constant output.',11);c='Wind turns a rotor connected to a generator. Token timing is illustrative; wind strength and delivered output vary.';}
 else{b=title('PRIMARY SOURCE → SECONDARY CARRIER')+box(20,70,190,'Gas / uranium','Finite resources')+box(230,70,190,'Wind / sun / water','Renewable flows')+box(110,235,220,'Electricity','Carrier: identify its source')+line('M115 140L200 228M325 140L240 228');c='A static source-to-carrier relationship. Electricity is not itself a renewable primary fuel, and the diagram is not a full national energy balance.';}
 }
 if(k==='dev-energy-natural-gas'){
 if(v==='supply'){b=title('EXTRACTION → PROCESSING → SERVICES')+`<path d="M20 185H420V302H20Z" fill="#6e8587"/><ellipse cx="95" cy="261" rx="55" ry="23" fill="#142c3d"/>`+line('M95 260V100H245','#e3c7a4',6)+token(95,260-160*t)+token(95+150*t,100)+box(240,65,180,'Process and transport','Pipes / staff / investment')+T(40,267,'Gas deposit',12)+T(20,331,'Finite fuel · jobs and useful services require infrastructure.',10);c='Symbolic gas extraction and transport; not a named field or actual depth, reserve, flow rate or employment total.';}
 else if(v==='dispatch'){b=title('ADJUST OUTPUT · FUEL MUST BE AVAILABLE')+box(20,70,180,'Available fuel + plant','Operating capacity')+box(240,70,180,'Demand rises','Adjust generation')+line('M200 103H233')+token(200+33*t,103)+`<rect x="45" y="200" width="350" height="65" rx="8" fill="#2c4a5d"/><rect x="45" y="200" width="${120+160*t}" height="65" rx="8" fill="#9ebca9"/>`+T(60,239,'Illustrative output response',16)+T(20,329,'Not a measured MW scale or guaranteed supply.',11);c='Conceptual dispatch with fuel and capacity available, not a real demand trace or universal ramp rate. Fuel prices, supply and plant limits constrain this advantage.';}
 else if(v==='emissions'){b=title('TWO DISTINCT CLIMATE PATHWAYS')+box(20,75,190,'Leak before burning','Methane escapes')+box(230,75,190,'Burn gas for services','Carbon dioxide released')+line('M115 240V150M325 240V150')+token(115,240-90*t,'#e4bc96')+token(325,240-90*t,'#b9cdb6')+T(30,278,'Production / pipes',12)+T(255,278,'Combustion',12)+T(20,329,'Different gases; dot counts are not an emissions inventory.',10);c='Leakage and combustion release different greenhouse gases. Symbols do not quantify equal warming, concentrations, leak rates or lifecycle emissions.';}
 else{b=title('NATURAL GAS · A CONDITIONAL JUDGEMENT')+box(20,70,400,'Potential benefits','Useful heat / adjustable power / jobs / revenue')+box(20,155,400,'Costs and risks','Finite fuel / prices / land / emissions / waste water')+box(20,240,400,'Evidence to compare','Who gains? Over what period? What is controlled?');c='A decision framework for gas development, not a universal verdict. Benefits and environmental burdens can fall on different groups.';}
 }
 if(k==='dev-energy-wind'){
 if(v==='rotor'||v==='low'){const low=v==='low';b=title(low?'LOW WIND · LOWER ILLUSTRATIVE OUTPUT':'WIND → ROTOR → GENERATOR → GRID')+windLines(t*(low?.25:1))+turbine(175,155,t*(low?.25:1),1)+box(280,98,140,'Generator','Grid connection')+line('M185 160L280 130')+token(185+95*t,160-30*t,'#b8ceba',low?3:6)+T(20,329,low?'Rated capacity is not constant delivered power.':'No fuel burning at the turbine; lifecycle impacts remain.',10);c=low?'An illustrative lower-wind comparison: rotor speed and token size indicate reduced output, not a calibrated wind-speed/power curve. Below cut-in or above cut-out, a real turbine may stop.':'A symbolic wind conversion mechanism. Rotor motion aids understanding, but this is not a turbine engineering model, output measurement or claim of zero lifecycle effects.';}
 else if(v==='balance'){b=title('VARIABLE SUPPLY NEEDS SYSTEM BALANCING')+turbine(92,145,t,.7)+box(230,65,190,'Other sources / demand','Connections and flexibility')+box(230,180,190,'Storage','Previously charged energy')+box(230,275,190,'Electricity services')+line('M95 240L225 300M325 138V172M325 247V268')+token(95+130*t,240+60*t)+token(325,247+21*t)+T(20,330,'Storage shifts energy in time; it does not create it.',10);c='A conceptual grid-balancing pathway, not a dispatch forecast or a promise that one battery meets all demand. Storage has energy, power and efficiency limits.';}
 else{b=title('SITE CHOICE · ENERGY AND LOCAL EFFECTS')+`<path d="M20 240Q100 170 220 240T420 240V300H20Z" fill="#789587"/>`+turbine(130,155,0,.7)+line('M230 100q30-25 60 0m-30 0q30-25 60 0','#e4d7bc',2)+box(235,180,185,'Survey and mitigate','Ecology / routes / noise')+T(20,329,'Also assess grid access, costs and community views.',10);c='A static siting sketch, not a real bird flight path or measured noise footprint. Marine habitats and maintenance need assessment for offshore developments too.';}
 }
 if(k==='dev-energy-uk-mix'){
 if(['mix','history'].includes(v))return energy01Evidence(v);s='uk';
 if(v==='groups'){b=title('GROUPED SOURCE CATEGORIES ARE NOT PURE TYPES')+box(20,65,400,'Primary electricity','Nuclear / wind / solar / hydro / net imports')+box(20,155,400,'Bioenergy and waste','Renewable and non-renewable components vary')+box(20,245,400,'Oil / gas / coal','Finite fossil fuels');c='Official grouped categories require definitions. Neither primary electricity nor all waste can automatically be labelled renewable.';}
 else{b=title('CHOOSE THE ACCOUNT BEFORE THE PERCENTAGE')+box(20,65,400,'Primary energy','Before conversion losses; several end uses')+box(20,155,400,'Final energy','Delivered for transport / heat / power / services')+box(20,245,400,'Electricity generation','Electricity produced; not all national energy');c='Three distinct accounting bases. Compare matching denominators and years, and do not add a primary fuel and its generated electricity as independent inputs.';}
 }
 return fig(b,c)+source(s);
}
